    tic; d_cof = cofdet(A); t_cof = toc;
    tic; d_leib = leibdet(A); t_leib = toc;
    tic; d_ref = det(A); t_det = toc;

    fprintf('%2d | %14.6e | %14.6e | %14.6e | %10.4f | %10.4f | %10.6f\n', ...
        n, d_cof, d_leib, d_ref, t_cof, t_leib, t_det);
end

function d = cofdet(A)
    n = size(A, 1);
    if n == 1
        d = A;
        return
    end
    d = 0;
    for j = 1:n
        B = A(2:end, [1:j-1, j+1:n]);
        d = d + (-1)^(1 + j) * A(1, j) * cofdet(B);
    end
end

function d = leibdet(A)
    n = size(A, 1);
    P = perms(1:n);          % 每一行是一个排列 sigma, 共 n! 行
    m = size(P, 1);

    % 统计逆序数并计算符号 sgn(sigma)
    inv_cnt = zeros(m, 1);
    for i = 1:n-1
        for j = i+1:n
            inv_cnt = inv_cnt + (P(:, i) > P(:, j));
        end
    end
    sgn = (-1).^inv_cnt;

    % 按列取 a_{sigma_j, j} 的乘积并加权求和
    prod_val = ones(m, 1);
    for j = 1:n
        prod_val = prod_val .* A(P(:, j), j);
    end
    d = sum(sgn .* prod_val);
end
```

**分析说明**：
- 精度上，`cofdet`、`leibdet` 与内建 `det` 所得数值在双精度浮点舍入误差（相对误差约 $10^{-15}$）范围内一致。
- 复杂度与运行时间增长规律：`cofdet` 递归满足 $T(n)=nT(n-1)+O(n^2)$，故时间复杂度为 $\Theta(n!)$（其中 $n$ 每增加 $1$，运行时间近似放大 $n$ 倍）；`leibdet` 需生成全部 $n!$ 个排列并统计逆序数与乘积，复杂度为 $\Theta(n^2\cdot n!)$（向量化后在 $n\le 9$ 时比纯循环递归更快，但同样呈阶乘级爆炸）；而 MATLAB 内建 `det` 基于 LU 分解，复杂度仅 $O(n^3)$，对 $n=3\sim 9$ 均在微秒至毫秒级内完成。

