function cnt = spantrees(n, edges)
    m = size(edges, 1);
    B = zeros(n, m);
    for k = 1:m
        u = edges(k, 1);
        v = edges(k, 2);
        B(u, k) = -1;
        B(v, k) = 1;
    end
    L = B * B';
    L0 = L(1:n-1, 1:n-1);    % 删去第 n 行与第 n 列
    cnt = round(det(L0));
end
```

