function c_out = hill_encrypt(text, K)
    v = double(upper(text)) - double('A');
    P = reshape(v, 2, []);
    C = mod(K * P, 26);
    c_out = char(C(:)' + double('A'));
end

function p_out = hill_decrypt(text, K)
    Kinv = hill_inv_mod26(K);
    v = double(upper(text)) - double('A');
    C = reshape(v, 2, []);
    P = mod(Kinv * C, 26);
    p_out = char(P(:)' + double('A'));
end

function Kinv = hill_inv_mod26(K)
    n = size(K, 1);
    d = mod(round(det(K)), 26);
    [g, u, ~] = gcd(d, 26);
    if g ~= 1
        error('det(K) is not coprime to 26.');
    end
    u = mod(u, 26);
    % 用整数余子式构造伴随矩阵以避免大阶或病态时的浮点误差
    adjK = zeros(n);
    for i = 1:n
        for j = 1:n
            sub = K([1:i-1, i+1:n], [1:j-1, j+1:n]);
            adjK(j, i) = (-1)^(i + j) * round(det(sub));
        end
    end
    Kinv = mod(u * adjK, 26);
end
```

